posts.text:
This is Error of PHPlib which is discused in phplib mailinglist \(for example http://www.geocrawler.com/archives/3/195/2000/10/0/4554958/\).

Unfortunatelly PHPlib have not fixed this error, yet \(ver7.3\). 

The suggested way, how to fix this bug \(http://www.geocrawler.com/archives/3/195/2000/11/0/4734731/\) does'n works well. So I rewrote PHPlib function ac\_store\(\) with REPLACE SQL command, and it looks it works:

function ac\_store\($id, $name, $str\) \{
$ret = true;

switch \( $this-&amp;gt;encoding\_mode \) \{
case &amp;quot;slashes&amp;quot;:
$str = addslashes\($name . &amp;quot;:&amp;quot; . $str\);
break;

case &amp;quot;base64&amp;quot;:
default:
$str = base64\_encode\($name . &amp;quot;:&amp;quot; . $str\);
\};

$name = addslashes\($name\);

\#\# update duration of visit
global $HTTP\_REFERER, $HTTP\_USER\_AGENT, $REMOTE\_ADDR;

$now = date\(&amp;quot;YmdHis&amp;quot;, time\(\)\);
$rquery = sprintf\(&amp;quot;replace %s \( sid, name, val, changed \) values \('%s', '%s', '%s', '%s'\)&amp;quot;,
$this-&amp;gt;database\_table,
$id,
$name,
$str,
$now\);

if\( \!$this-&amp;gt;db-&amp;gt;query\($rquery\) \)
$ret = false;

return $ret;
\}

\--------- old one:
function ac\_store\($id, $name, $str\) \{
$ret = true;

switch \( $this-&amp;gt;encoding\_mode \) \{
case &amp;quot;slashes&amp;quot;:
$str = addslashes\($name . &amp;quot;:&amp;quot; . $str\);
break;

case &amp;quot;base64&amp;quot;:
default:
$str = base64\_encode\($name . &amp;quot;:&amp;quot; . $str\);
\};

$name = addslashes\($name\);

\#\# update duration of visit
global $HTTP\_REFERER, $HTTP\_USER\_AGENT, $REMOTE\_ADDR;

$now = date\(&amp;quot;YmdHis&amp;quot;, time\(\)\);
$uquery = sprintf\(&amp;quot;update %s set val='%s', changed='%s' where sid='%s' and name='%s'&amp;quot;,
$this-&amp;gt;database\_table,
$str,
$now,
$id,
$name\);
$squery = sprintf\(&amp;quot;select count\(\*\) from %s where val='%s' and changed='%s' and sid='%s' and na
me='%s'&amp;quot;,
$this-&amp;gt;database\_table,
$str,
$now,
$id,
$name\);
$iquery = sprintf\(&amp;quot;insert into %s \( sid, name, val, changed \) values \('%s', '%s', '%s', '%s'\)&amp;quot;
,
$this-&amp;gt;database\_table,
$id,
$name,
$str,
$now\);

$this-&amp;gt;db-&amp;gt;query\($uquery\);

\# FIRST test to see if any rows were affected.
\#   Zero rows affected could mean either there were no matching rows
\#   whatsoever, OR that the update statement did match a row but made
\#   no changes to the table data \(i.e. UPDATE tbl SET col = 'x', when
\#   &amp;quot;col&amp;quot; is \_already\_ set to 'x'\) so then,
\# SECOND, query\(SELECT...\) on the sid to determine if the row is in
\#   fact there,
\# THIRD, verify that there is at least one row present, and if there
\#   is not, then
\# FOURTH, insert the row as we've determined that it does not exist.

if \( $this-&amp;gt;db-&amp;gt;affected\_rows\(\) == 0 // ERROR in PHPlib with php4
&amp;amp;&amp;amp; $this-&amp;gt;db-&amp;gt;query\($squery\)
&amp;amp;&amp;amp; $this-&amp;gt;db-&amp;gt;f\(1\) == 0
&amp;amp;&amp;amp; \!$this-&amp;gt;db-&amp;gt;query\($iquery\)\) \{

$ret = false;
\}
return $ret;
\}

